#pragma once
#include "model_guard.hpp"
namespace snuw {
inline const std::vector<std::string> panelExtraSettings={"workflow_profile","render_mode","genre","width","height","count","seed","version","quality_tags","save_metadata","initial_image","enhance","use_default_negative","ip_weight","ip_end","pose_strength","pose_end","consistency_enabled","consistency_profile","style_profile","learn_preferences","learning_vision_model","_model_settings","_pixel_active","_before_pixel","_before_pixel_model","_previous_workflow"};
inline std::set<std::string> panelSettings(){std::set<std::string> out(modelPreferenceKeys.begin(),modelPreferenceKeys.end());out.insert(panelExtraSettings.begin(),panelExtraSettings.end());return out;}
inline json panelSnapshot(const json& state){json settings=json::object();auto cfg=state.value("settings",json::object());for(auto& key:panelSettings())if(cfg.contains(key))settings[key]=cfg[key];json out={{"settings",settings},{"drafts",state.value("drafts",json::object())},{"negative",state.value("negative",json(""))},{"project",json::object()}};auto project=state.value("project",json::object());for(auto key:{"prompt_sections","negative","references","enhance","use_default_negative"})if(project.contains(key))out["project"][key]=project[key];for(auto key:{"_prompt_document_version","_prompt_linked","_prompt_error","_prompt_legacy_backup","_entity_expectations"})if(state.contains(key))out[key]=state[key];return out;}
inline void applyPanelSnapshot(json& state,const json& snapshot){auto& cfg=state["settings"];for(auto& key:panelSettings())cfg.erase(key);cfg.update(snapshot.value("settings",json::object()));state["drafts"]=snapshot.value("drafts",json::object());state["negative"]=snapshot.value("negative",json(""));for(auto key:{"prompt_sections","negative","references","enhance","use_default_negative"}){state["project"].erase(key);if(snapshot.value("project",json::object()).contains(key))state["project"][key]=snapshot["project"][key];}for(auto key:{"_prompt_document_version","_prompt_linked","_prompt_error","_prompt_legacy_backup","_entity_expectations"}){state.erase(key);if(snapshot.contains(key))state[key]=snapshot[key];}}
inline bool boardId(const std::string& value){return value.size()==32&&value.find_first_not_of("0123456789abcdef")==std::string::npos;}
inline json& boardPage(json& board,const std::string& key){for(auto& page:board["pages"])if(str(page,"id")==key)return page;throw std::runtime_error("페이지를 찾을 수 없습니다.");}
inline json& boardPanel(json& board,const std::string& page,const std::string& panel){for(auto& row:boardPage(board,page)["panels"])if(str(row,"id")==panel)return row;throw std::runtime_error("컷을 찾을 수 없습니다.");}
inline json& activeBoardPanel(json& board){return boardPanel(board,str(board,"active_page"),str(board,"active_panel"));}
inline void validatePanelSnapshot(const json& snapshot){if(!snapshot.is_object()||snapshot.dump().size()>1024*1024)throw std::runtime_error("컷 설정 크기나 형식을 확인하세요.");auto settings=snapshot.value("settings",json::object());if(!settings.is_object())throw std::runtime_error("컷 설정 형식 오류");auto modelKeys=std::set<std::string>(modelPreferenceKeys.begin(),modelPreferenceKeys.end());auto checkModel=[&](const json& values,bool pixel){if(!values.is_object())throw std::runtime_error("모델 기준 설정 형식을 확인하세요.");for(auto it=values.begin();it!=values.end();++it)if(!modelKeys.count(it.key())&&!(pixel&&it.key()=="initial_image"))throw std::runtime_error("모델 기준에 계정·서버 설정을 넣을 수 없습니다.");};if(settings.contains("_model_settings")){auto cache=settings["_model_settings"];if(!cache.is_object()||cache.size()>16)throw std::runtime_error("모델 설정 목록을 확인하세요.");for(auto& item:cache.items())checkModel(item.value(),false);}if(settings.contains("_before_pixel"))checkModel(settings["_before_pixel"],true);auto allowed=panelSettings();for(auto it=settings.begin();it!=settings.end();++it)if(!allowed.count(it.key()))throw std::runtime_error("컷에 계정·저장 위치 설정을 넣을 수 없습니다.");if(!snapshot.value("drafts",json::object()).is_object()||!snapshot.value("negative",json("")).is_string()||!snapshot.value("project",json::object()).is_object())throw std::runtime_error("컷 프롬프트 형식 오류");}
inline void validateStoryboard(json board){if(!board.is_object()||board.value("version",0)!=1||!board.contains("pages")||!board["pages"].is_array()||board["pages"].empty()||board["pages"].size()>100||board.dump().size()>16*1024*1024)throw std::runtime_error("페이지 구조나 용량을 확인하세요.");validatePanelSnapshot(board.at("defaults"));std::set<std::string> keys;size_t count=0;for(auto& page:board["pages"]){auto key=str(page,"id"),name=str(page,"name");if(!boardId(key)||!keys.insert(key).second||name.empty()||name.size()>400||!page.contains("panels")||!page["panels"].is_array()||page["panels"].empty())throw std::runtime_error("페이지 이름·식별값·컷 목록을 확인하세요.");validatePanelSnapshot(page.at("defaults"));for(auto& panel:page["panels"]){auto panelKey=str(panel,"id"),title=str(panel,"name");if(!boardId(panelKey)||!keys.insert(panelKey).second||title.empty()||title.size()>400||++count>1000)throw std::runtime_error("컷 이름·식별값·개수를 확인하세요.");validatePanelSnapshot(panel.at("snapshot"));validatePanelSnapshot(panel.at("baseline"));if(panel.contains("previous"))validatePanelSnapshot(panel["previous"]);}}activeBoardPanel(board);auto trash=board.value("trash",json::array());if(!trash.is_array()||trash.size()>10)throw std::runtime_error("삭제 복원 기록을 확인하세요.");}
inline json initialStoryboard(const json& state){auto snapshot=panelSnapshot(state);auto page=id(),panel=id();return {{"version",1},{"defaults",snapshot},{"active_page",page},{"active_panel",panel},{"pages",json::array({{{"id",page},{"name","1페이지"},{"defaults",snapshot},{"panels",json::array({{{"id",panel},{"name","1컷"},{"legacy_images",true},{"snapshot",snapshot},{"baseline",snapshot},{"selected",state.value("selected",json(nullptr))}}})}}})},{"trash",json::array()}};}
inline json portableStoryboard(json board,bool importing=false){validateStoryboard(board);board["trash"]=json::array();auto clean=[&](json& snapshot){snapshot.erase("_prompt_legacy_backup");if(importing)snapshot.erase("_entity_expectations");};clean(board["defaults"]);for(auto& page:board["pages"]){clean(page["defaults"]);for(auto& panel:page["panels"]){clean(panel["snapshot"]);clean(panel["baseline"]);panel.erase("previous");panel.erase("selected");}}return board;}
inline json cloneStoryboard(json board){validateStoryboard(board);auto activePage=str(board,"active_page"),activePanel=str(board,"active_panel");board["trash"]=json::array();for(auto& page:board["pages"]){auto old=str(page,"id"),next=id();page["id"]=next;if(old==activePage)board["active_page"]=next;for(auto& panel:page["panels"]){auto oldPanel=str(panel,"id"),nextPanel=id();panel["id"]=nextPanel;panel["selected"]=nullptr;panel.erase("previous");panel.erase("legacy_images");if(oldPanel==activePanel)board["active_panel"]=nextPanel;}}return board;}
struct PanelGalleryFilter {std::string active;bool legacy=false;std::set<std::string> known;explicit PanelGalleryFilter(const json& board){if(board.is_null()||board.empty())return;active=str(board,"active_panel");for(auto& page:board.at("pages"))for(auto& panel:page.at("panels")){auto key=str(panel,"id");known.insert(key);if(key==active)legacy=flag(panel,"legacy_images");}}bool visible(const std::string& panel)const{return active.empty()||panel==active||legacy&&panel.empty();}};
inline bool panelGalleryVisible(const json& board,const std::string& imagePanel){return PanelGalleryFilter(board).visible(imagePanel);}

}
